        return preg_replace('/[^a-z]/', '', strtolower($w));
    }

    public function up(): void
    {
        try {
            $this->add();
        } catch (\Throwable $e) {
            Log::error('[med-new-words] aborted, nothing was changed: ' . $e->getMessage());
        }
    }

    private function skip(string $why): void
    {
        Log::warning('[med-new-words] skipped, nothing was changed: ' . $why);
    }

    private function add(): void
    {
        foreach (['chapters', 'lessons', 'words'] as $t) {
            if (!Schema::hasTable($t)) { $this->skip("table {$t} missing"); return; }
        }
        if (Schema::hasTable(self::BACKUP)) { $this->skip('already applied (backup table exists)'); return; }

        $chapter = DB::table('chapters')->where('title', self::PROBABLE_TITLE)->orderBy('id')->first();
        if (!$chapter) { $this->skip('target chapter not found'); return; }

        $lessonIds = DB::table('lessons')->where('chapter_id', $chapter->id)->orderBy('id')->pluck('id')->all();
        if (count($lessonIds) !== 4) { $this->skip('chapter has ' . count($lessonIds) . ' lessons, expected 4'); return; }
        $existing = DB::table('words')->whereIn('lesson_id', $lessonIds)->count();
        if ($existing !== 113) { $this->skip("chapter has {$existing} words, expected 113"); return; }

        $template = DB::table('lessons')->where('id', $lessonIds[0])->first();
        if (!$template) { $this->skip('template lesson not found'); return; }

        // every word already in the vocabulary tables
        $have = [];
        foreach (DB::table('words')->pluck('word') as $w) { $have[$this->norm((string) $w)] = true; }

        $specs = [];
        $dropped = 0;
        foreach ($this->lessons() as $l) {
            $words = [];
            foreach ($l['words'] as [$word, $meaning, $synonym, $importance]) {
                $n = $this->norm($word);
                if ($n === '' || isset($have[$n])) { $dropped++; continue; }
                $have[$n] = true;
                $words[] = [$word, $meaning, $synonym, $importance];
            }
            if ($words) { $specs[] = ['title' => $l['title'], 'words' => $words]; }
        }
        $expectedTotal = array_sum(array_map(fn ($s) => count($s['words']), $specs));
        if ($expectedTotal < 700) { $this->skip("only {$expectedTotal} insertable words (dropped {$dropped}), expected ~907"); return; }

        $hasLayout = Schema::hasColumn('lessons', 'layout');

        // DDL commits implicitly -> create the backup table BEFORE the transaction
        Schema::create(self::BACKUP, function ($t) {
            $t->id();
            $t->string('kind', 10)->index();   // lesson | word
            $t->unsignedBigInteger('ref_id');
        });

        try {
            DB::transaction(function () use ($specs, $template, $chapter, $lessonIds, $expectedTotal, $hasLayout) {
                $now = now();
                $inserted = 0;
                foreach ($specs as $s) {
                    $row = (array) $template;
                    unset($row['id']);
                    $row['title']      = $s['title'];
                    $row['chapter_id'] = $chapter->id;
                    $row['col1_label'] = 'শব্দ';
                    $row['col2_label'] = 'অর্থ';
                    $row['col3_label'] = '🔤 English Synonym';
                    $row['col4_label'] = '📊 গুরুত্ব %';
                    $row['is_premium'] = 0;
                    $row['created_at'] = $now;
                    $row['updated_at'] = $now;
                    if ($hasLayout) { $row['layout'] = 'stacked'; }
                    $lessonId = DB::table('lessons')->insertGetId($row);
                    DB::table(self::BACKUP)->insert(['kind' => 'lesson', 'ref_id' => $lessonId]);

                    foreach ($s['words'] as [$word, $meaning, $synonym, $importance]) {
                        $wid = DB::table('words')->insertGetId([
                            'word'       => $word,
                            'meaning'    => $meaning,
                            'synonyms'   => $synonym,
                            'antonyms'   => $importance,
                            'type'       => 'both',
                            'lesson_id'  => $lessonId,
                            'status'     => 1,
                            'created_at' => $now,
                            'updated_at' => $now,
                        ]);
                        DB::table(self::BACKUP)->insert(['kind' => 'word', 'ref_id' => $wid]);
                        $inserted++;
                    }
                    $count = DB::table('words')->where('lesson_id', $lessonId)->count();
                    if ($count !== count($s['words'])) {
                        throw new \RuntimeException("lesson {$lessonId}: expected " . count($s['words']) . " words, found {$count}");
                    }
                }
                if ($inserted !== $expectedTotal) {
                    throw new \RuntimeException("inserted {$inserted}, expected {$expectedTotal}");
                }
                if (DB::table('words')->whereIn('lesson_id', $lessonIds)->count() !== 113) {
                    throw new \RuntimeException('original 4 lessons changed word count');
                }
            });
        } catch (\Throwable $e) {
            Schema::dropIfExists(self::BACKUP);   // allow a clean re-run after a failed attempt
            throw $e;
        }

        Log::info('[med-new-words] done: added ' . count($specs) . " lessons / {$expectedTotal} words (skipped {$dropped} duplicates)");
    }

    public function down(): void
    {
        if (!Schema::hasTable(self::BACKUP)) {
